param([string]$RunId='')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78WindowsTailResults";$exe="$root\Build\Release\m78_combined-v2_concave.exe";$lib="$root\M78ContinuationBuild\combined-v2\judas_engine.lib"
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 if($RunId -notmatch '^original-[1-3]$'){throw 'One explicit original repeat required'};$name="m78-windows-tail-$RunId";$dir="$out\$RunId";if(Test-Path $dir){throw 'Preserve prior repeat'};if((Get-PSDrive C).Free -lt 20MB){throw 'Insufficient bounded output headroom'}
 if((Get-FileHash $exe).Hash.ToLower() -ne 'bd10e97e8998af0ca8eeb3214bfa791cd266d2b7c816c918141a77457e89d903' -or (Get-FileHash $lib).Hash.ToLower() -ne '791edc06d69e9a0c750c2bf23f91b20936ed5c0d530f20a936eed0c544c9ba48'){throw 'Frozen final binary mismatch'}
 $env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";New-Item -ItemType Directory $dir|Out-Null;$before=[DateTime]::UtcNow;$watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath $exe -WorkingDirectory "$root\Source" -ArgumentList @($dir) -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(180000)){Stop-Process -Id $p.Id -Force;throw 'Owned original repeat timed out'};$p.Refresh();$watch.Stop();$exit=$p.ExitCode;$cpu=$p.TotalProcessorTime.TotalMilliseconds;$files=@();foreach($file in @(Get-ChildItem $dir -File)){ $n="$name-$($file.Name)";Upload $file.FullName $n;$files+=@{path=$file.FullName;reportName=$n;bytes=$file.Length;sha256=(Get-FileHash $file.FullName).Hash.ToLower()}}
 $receipt="$out\$name.json";@{scope='Unchanged original 4-case 900-step60Hz native benchmark, exact frozen exe/library; no source/quality/cadence changes';utcBefore=$before.ToString('o');seconds=$watch.Elapsed.TotalSeconds;processCpuMs=$cpu;exitCode=$exit;exeSHA256='bd10e97e8998af0ca8eeb3214bfa791cd266d2b7c816c918141a77457e89d903';librarySHA256='791edc06d69e9a0c750c2bf23f91b20936ed5c0d530f20a936eed0c544c9ba48';files=$files;freeBytes=(Get-PSDrive C).Free;environment=@{GALLIUM_DRIVER=$env:GALLIUM_DRIVER;JUDAS_ENGINE_ROOT=$env:JUDAS_ENGINE_ROOT}}|ConvertTo-Json -Depth 6|Set-Content $receipt -Encoding UTF8;Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";Upload $receipt "$name.json"
}catch{$p="$out\m78-windows-tail-$RunId-error.txt";[string]$_.Exception.Message|Set-Content $p;Upload $p ([IO.Path]::GetFileName($p));exit 1}
